package net.minecraft.client.gui.components;import net.minecraft.network.chat.Component;import java.util.function.Consumer;public class Button extends AbstractWidget {private Component message;private final Consumer<Button> action;Button(Component m,Consumer<Button> a){message=m;action=a;}public void onPress(){action.accept(this);}public void setMessage(Component m){message=m;}public Component getMessage(){return message;}public static Builder builder(Component m,Consumer<Button> a){return new Builder(m,a);}public record Builder(Component m,Consumer<Button> a){public Builder bounds(int x,int y,int w,int h){return this;}public Button build(){return new Button(m,a);}}}